-- =========================================================
--  HOSPITAL MANAGEMENT DATASET
--  Database: Hospital_Management
--  Tables: departments, doctors, patients, rooms, appointments,
--          admissions, prescriptions, billing
--  Notes: synthetic data; timelines are consistent (registration <
--         appointment/admission < discharge; bills only for completed
--         visits and discharged stays; no overlapping room stays);
--         UNIQUE constraints on department_name, email, room_number
-- =========================================================

CREATE DATABASE IF NOT EXISTS Hospital_Management;
USE Hospital_Management;

-- ---------------------------------------------------------
-- DEPARTMENTS TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS departments (
    department_id INT PRIMARY KEY,
    department_name VARCHAR(80) NOT NULL UNIQUE,
    location VARCHAR(80),
    phone VARCHAR(20)
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;

-- ---------------------------------------------------------
-- DOCTORS TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS doctors (
    doctor_id INT PRIMARY KEY,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    specialization VARCHAR(80),
    department_id INT NOT NULL,
    phone VARCHAR(20),
    email VARCHAR(100) NOT NULL UNIQUE,
    hire_date DATE,
    consultation_fee DECIMAL(10 , 2 ),
    FOREIGN KEY (department_id)
        REFERENCES departments (department_id)
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;

-- ---------------------------------------------------------
-- PATIENTS TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS patients (
    patient_id INT PRIMARY KEY,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    gender VARCHAR(10),
    date_of_birth DATE,
    blood_group VARCHAR(5),
    phone VARCHAR(20),
    email VARCHAR(100) UNIQUE,
    city VARCHAR(80),
    registration_date DATE
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;

-- ---------------------------------------------------------
-- ROOMS TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS rooms (
    room_id INT PRIMARY KEY,
    room_number VARCHAR(10) NOT NULL UNIQUE,
    room_type VARCHAR(30),
    department_id INT NOT NULL,
    daily_rate DECIMAL(10 , 2 ),
    FOREIGN KEY (department_id)
        REFERENCES departments (department_id)
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;

-- ---------------------------------------------------------
-- APPOINTMENTS TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS appointments (
    appointment_id INT PRIMARY KEY,
    patient_id INT NOT NULL,
    doctor_id INT NOT NULL,
    appointment_date DATETIME,
    status VARCHAR(20),
    reason VARCHAR(150),
    FOREIGN KEY (patient_id)
        REFERENCES patients (patient_id),
    FOREIGN KEY (doctor_id)
        REFERENCES doctors (doctor_id)
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;

-- ---------------------------------------------------------
-- ADMISSIONS TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS admissions (
    admission_id INT PRIMARY KEY,
    patient_id INT NOT NULL,
    doctor_id INT NOT NULL,
    room_id INT NOT NULL,
    admission_date DATETIME,
    discharge_date DATETIME NULL,
    diagnosis VARCHAR(150),
    FOREIGN KEY (patient_id)
        REFERENCES patients (patient_id),
    FOREIGN KEY (doctor_id)
        REFERENCES doctors (doctor_id),
    FOREIGN KEY (room_id)
        REFERENCES rooms (room_id)
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;

-- ---------------------------------------------------------
-- PRESCRIPTIONS TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS prescriptions (
    prescription_id INT PRIMARY KEY,
    appointment_id INT NOT NULL,
    medicine_name VARCHAR(80) NOT NULL,
    category VARCHAR(50),
    dosage VARCHAR(50),
    duration_days INT,
    FOREIGN KEY (appointment_id)
        REFERENCES appointments (appointment_id)
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;

-- ---------------------------------------------------------
-- BILLING TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS billing (
    bill_id INT PRIMARY KEY,
    patient_id INT NOT NULL,
    appointment_id INT NULL,
    admission_id INT NULL,
    bill_date DATE,
    total_amount DECIMAL(12 , 2 ),
    payment_status VARCHAR(20),
    payment_method VARCHAR(20),
    FOREIGN KEY (patient_id)
        REFERENCES patients (patient_id),
    FOREIGN KEY (appointment_id)
        REFERENCES appointments (appointment_id),
    FOREIGN KEY (admission_id)
        REFERENCES admissions (admission_id)
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;


